fieldBindings.expression:
{(v) => {
              if (v === '' || v.includes('{')) {
                onChange('tabIndex', v)
              } else {
                const num = parseInt(v)
                onChange('tabIndex', isNaN(num) ? v : num)
              }
            }}

{(v) => {
            const milliseconds = typeof v === 'number' ? v * 1000 : 60000
            onChange('timeout', milliseconds)
          }}

